#include <bits/stdc++.h>
using namespace std;

static string in;
static size_t p = 0;
static void readAll() {
    char b[1 << 16];
    size_t k;
    while ((k = fread(b, 1, sizeof b, stdin)) > 0) in.append(b, k);
}
static bool skipSpace() {
    while (p < in.size() && (unsigned char)in[p] <= ' ') p++;
    return p < in.size();
}
static string token() {
    skipSpace();
    size_t s = p;
    while (p < in.size() && (unsigned char)in[p] > ' ') p++;
    return in.substr(s, p - s);
}
static long long num() {
    skipSpace();
    bool neg = false;
    if (p < in.size() && (in[p] == '-' || in[p] == '+')) neg = in[p++] == '-';
    long long v = 0;
    while (p < in.size() && in[p] >= '0' && in[p] <= '9') v = v * 10 + (in[p++] - '0');
    return neg ? -v : v;
}

int main() {
    readAll();
    long long n = num(), total = 0;
    const long long MOD = 1000000007;
    // Sum of i mod j over i = 1..n: q full cycles 0..j-1 plus a tail 0..r.
    for (long long j = 1; j <= n; j++) {
        long long q = n / j, r = n % j;
        total = (total + q * j * (j - 1) / 2 + r * (r + 1) / 2) % MOD;
    }
    // C(i, j) is symmetric, so the answer doubles that sum.
    printf("%lld\n", 2 * total % MOD);
}

