package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := num()
	var total int64
	const mod = 1000000007
	// Sum of i mod j over i = 1..n: q full cycles 0..j-1 plus a tail 0..r.
	for j := int64(1); j <= n; j++ {
		q, r := n/j, n%j
		total = (total + q*j*(j-1)/2 + r*(r+1)/2) % mod
	}
	// C(i, j) is symmetric, so the answer doubles that sum.
	fmt.Println(2 * total % mod)
}
